use is_libc_used::is_libc_used;
use std::path::Path;
use std::process::ExitCode;

fn main() -> ExitCode {
    // Find the binary - look relative to workspace root
    let manifest_dir = env!("CARGO_MANIFEST_DIR");
    let workspace_root = Path::new(manifest_dir)
        .parent()
        .and_then(|p| p.parent())
        .expect("should find workspace root");

    // Try release first, then debug
    let release_path = workspace_root.join("target/release/ex-x1");
    let debug_path = workspace_root.join("target/debug/ex-x1");

    let path = if release_path.exists() {
        release_path
    } else if debug_path.exists() {
        debug_path
    } else {
        eprintln!("SKIP: ex-x1 binary not found (build with 'cargo build -p ex-x1' first)");
        return ExitCode::SUCCESS;
    };

    println!("Testing: {}", path.display());

    let result = match is_libc_used(&path) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("FAIL: failed to parse binary: {}", e);
            return ExitCode::FAILURE;
        }
    };

    if result.uses_libc {
        eprintln!("FAIL: ex-x1 should NOT use libc");
        for info in &result.info {
            eprintln!("  {}", info);
        }
        ExitCode::FAILURE
    } else {
        println!("PASS: ex-x1 does not use libc");
        for info in &result.info {
            println!("  {}", info);
        }
        ExitCode::SUCCESS
    }
}

